// Generated by csrgen. APB3, 32-bit data, no byte strobes.
// rw1c: hardware set wins over software clear.
module apb_csr #(
    parameter integer AW = 16
) (
    input  logic           pclk,
    input  logic           presetn,
    input  logic           psel,
    input  logic           penable,
    input  logic           pwrite,
    input  logic [AW-1:0]  paddr,
    input  logic [31:0]    pwdata,
    output logic [31:0]    prdata,
    output logic           pready,
    output logic           pslverr,
    output logic           a,
    input  logic [1:0]     b,
    output logic [27:0]    c,
    input  logic [27:0]    c_hwset,
    output logic           a1,
    input  logic [1:0]     b1,
    output logic [27:0]    c1,
    input  logic [27:0]    c1_hwset
);

    localparam logic [AW-1:0] OFFSET_0x0 = AW'(32'h00000000);
    localparam logic [AW-1:0] OFFSET_0x4 = AW'(32'h00000004);

    logic csr_addr_hit;
    logic [31:0] csr_data;
    logic csr_write;
    logic csr_read;
    logic [31:0] csr_reg_data_0x0; // offset 0x0
    logic [31:0] csr_reg_data_0x4; // offset 0x4

    assign pready = 1'b1;
    assign pslverr = psel && penable && !csr_addr_hit;
    assign csr_write = psel && penable && pwrite && pready && !pslverr;
    // Capture read data at the end of SETUP, before ACCESS completes.
    assign csr_read = psel && !penable && !pwrite && csr_addr_hit;

    always_comb begin
        csr_addr_hit = 1'b0;
        case (paddr)
            OFFSET_0x0: csr_addr_hit = 1'b1;
            OFFSET_0x4: csr_addr_hit = 1'b1;
            default: csr_addr_hit = 1'b0;
        endcase
    end

    always_comb begin
        csr_data = 32'b0;
        if (csr_read) begin
            case (paddr)
                OFFSET_0x0: csr_data = csr_reg_data_0x0;
                OFFSET_0x4: csr_data = csr_reg_data_0x4;
                default: csr_data = 32'b0;
            endcase
        end
    end

    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn)
            prdata <= 32'b0;
        else if (csr_read)
            prdata <= csr_data;
    end

    assign csr_reg_data_0x0 = {
        1'b0, // bit 31, reset 1'h0, ro, reserved (tie0)
        c,    // bits 30:3, reset 28'h0, rw1c
        b,    // bits 2:1, reset 2'h1, ro
        a     // bit 0, reset 1'h1, rw
    };

    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn)
            a <= 1'h1;
        else if (csr_write && paddr == OFFSET_0x0)
            a <= pwdata[0];
    end

    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn)
            c <= 28'h0;
        else if (csr_write && paddr == OFFSET_0x0)
            c <= (c & ~pwdata[30:3]) | c_hwset;
        else
            c <= c | c_hwset;
    end

    assign csr_reg_data_0x4 = {
        1'b0, // bit 31, reset 1'h0, ro, reserved (tie0)
        c1,   // bits 30:3, reset 28'h0, rw1c
        b1,   // bits 2:1, reset 2'h1, ro
        a1    // bit 0, reset 1'h1, rw
    };

    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn)
            a1 <= 1'h1;
        else if (csr_write && paddr == OFFSET_0x4)
            a1 <= pwdata[0];
    end

    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn)
            c1 <= 28'h0;
        else if (csr_write && paddr == OFFSET_0x4)
            c1 <= (c1 & ~pwdata[30:3]) | c1_hwset;
        else
            c1 <= c1 | c1_hwset;
    end

endmodule
